const crypto = require('crypto');
const headers = $json.headers ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) {
  return [{ json: { ok: false, statusCode: 401, error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
const asObj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
let body = asObj($json.body);
if (!Object.keys(body).length && typeof $json.body === 'string') {
  try { body = asObj(JSON.parse($json.body)); } catch {}
}
if (!Object.keys(body).length) body = asObj($json);

const timeline_type = String(body.timeline_type || '').trim().toLowerCase();
const mission_id = String(body.mission_id || '').trim();
const run_id = String(body.run_id || '').trim();
const udn_line = String(body.udn_line || '').trim();
const artifact_ref = String(body.artifact_ref || '').trim();
const source = String(body.source || 'timeline-writer').trim() || 'timeline-writer';
const executor_id = String(body.executor_id || '').trim();
const performed_by = String(body.performed_by || '').trim();
const context_summary = String(body.context_summary || '').trim();
const context_payload = asObj(body.context_payload);
let occurred_at = String(body.occurred_at || '').trim();
if (!occurred_at) occurred_at = new Date().toISOString();
const occurredDate = new Date(occurred_at);
if (!Number.isFinite(occurredDate.getTime())) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'OCCURRED_AT_INVALID', message: 'occurred_at must be valid ISO datetime' } }];
}

if (!['dev','evl'].includes(timeline_type)) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'TIMELINE_TYPE_INVALID', message: 'timeline_type must be dev|evl' } }];
}
if (!mission_id || !udn_line || !executor_id || !performed_by) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'TIMELINE_PAYLOAD_INVALID', message: 'mission_id, udn_line, executor_id and performed_by are required' } }];
}
if (timeline_type === 'dev' && !udn_line.startsWith('!DEV|')) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_DEV_INVALID', message: 'udn_line must start with !DEV|' } }];
}
if (timeline_type === 'evl' && !udn_line.startsWith('!EVL|')) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_EVL_INVALID', message: 'udn_line must start with !EVL|' } }];
}

const esc = (v) => String(v ?? '').replace(/'/g, "''");
const contextPayloadJson = JSON.stringify(context_payload);

if (timeline_type === 'dev') {
  const parts = udn_line.replace(/;\s*$/, '').split('|');
  if (parts.length < 6) {
    return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_DEV_PARTS_INVALID', message: 'expected !DEV|PHASE|DUR|MS|EXEC|QG;' } }];
  }
  const phase = String(parts[1] || '').trim();
  const duration_ref = String(parts[2] || '').trim();
  const milestone = String(parts[3] || '').trim();
  const prompt_executor = String(parts[4] || '').trim();
  const quality_gate = String(parts[5] || '').trim();
  if (!phase || !duration_ref || !milestone || !prompt_executor || !quality_gate) {
    return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_DEV_FIELDS_INVALID', message: 'missing DEV fields' } }];
  }
  const canon = JSON.stringify({timeline_type, mission_id, run_id, executor_id, performed_by, occurred_at: occurredDate.toISOString(), phase, duration_ref, milestone, prompt_executor, quality_gate, context_summary, context_payload: context_payload, udn_line, artifact_ref, source});
  const event_hash = crypto.createHash('sha256').update(Buffer.from(canon, 'utf8')).digest('hex');
  return [{ json: { ok: true, route: 'dev', timeline_type, mission_id, run_id, executor_id, performed_by, occurred_at: occurredDate.toISOString(), phase, duration_ref, milestone, prompt_executor, quality_gate, context_summary, context_payload_json: contextPayloadJson, udn_line, artifact_ref, source, event_hash, mission_id_sql: esc(mission_id), run_id_sql: esc(run_id), executor_id_sql: esc(executor_id), performed_by_sql: esc(performed_by), occurred_at_sql: esc(occurredDate.toISOString()), phase_sql: esc(phase), duration_ref_sql: esc(duration_ref), milestone_sql: esc(milestone), prompt_executor_sql: esc(prompt_executor), quality_gate_sql: esc(quality_gate), context_summary_sql: esc(context_summary), context_payload_sql: esc(contextPayloadJson), udn_line_sql: esc(udn_line), artifact_ref_sql: esc(artifact_ref), source_sql: esc(source), event_hash_sql: esc(event_hash) } }];
}

const parts = udn_line.replace(/;\s*$/, '').split('|');
if (parts.length < 5) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_EVL_PARTS_INVALID', message: 'expected !EVL|TIMELINE|EVENT|STAFF_ACT|ART;' } }];
}
const timeline_ref = String(parts[1] || '').trim();
const event_name = String(parts[2] || '').trim();
const staff_action = String(parts[3] || '').trim();
const art_ref_from_udn = String(parts[4] || '').trim();
if (!timeline_ref || !event_name || !staff_action || !art_ref_from_udn) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'UDN_EVL_FIELDS_INVALID', message: 'missing EVL fields' } }];
}
const art_final = artifact_ref || art_ref_from_udn;
const canon = JSON.stringify({timeline_type, mission_id, run_id, executor_id, performed_by, occurred_at: occurredDate.toISOString(), timeline_ref, event_name, staff_action, context_summary, context_payload: context_payload, artifact_ref: art_final, udn_line, source});
const event_hash = crypto.createHash('sha256').update(Buffer.from(canon, 'utf8')).digest('hex');
return [{ json: { ok: true, route: 'evl', timeline_type, mission_id, run_id, executor_id, performed_by, occurred_at: occurredDate.toISOString(), timeline_ref, event_name, staff_action, context_summary, context_payload_json: contextPayloadJson, artifact_ref: art_final, udn_line, source, event_hash, mission_id_sql: esc(mission_id), run_id_sql: esc(run_id), executor_id_sql: esc(executor_id), performed_by_sql: esc(performed_by), occurred_at_sql: esc(occurredDate.toISOString()), timeline_ref_sql: esc(timeline_ref), event_name_sql: esc(event_name), staff_action_sql: esc(staff_action), context_summary_sql: esc(context_summary), context_payload_sql: esc(contextPayloadJson), artifact_ref_sql: esc(art_final), udn_line_sql: esc(udn_line), source_sql: esc(source), event_hash_sql: esc(event_hash) } }];
